CREATE TABLE public.app_user_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, connector_id text NOT NULL, connection_key_ciphertext text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,connector_id));
GRANT ALL ON public.app_user_connections TO service_role;
ALTER TABLE public.app_user_connections ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.integration_jobs (id text PRIMARY KEY, user_id uuid NOT NULL, kind text NOT NULL, status text NOT NULL DEFAULT 'processing', error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.integration_jobs TO service_role;
ALTER TABLE public.integration_jobs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.linq_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, provider_message_id text UNIQUE, chat_id text, body text NOT NULL, direction text NOT NULL CHECK(direction IN ('inbound','outbound')), delivery_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.linq_messages TO authenticated;
GRANT ALL ON public.linq_messages TO service_role;
ALTER TABLE public.linq_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY linq_messages_owner_read ON public.linq_messages FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.linq_webhook_receipts (id text PRIMARY KEY, status text NOT NULL DEFAULT 'processing', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.linq_webhook_receipts TO service_role;
ALTER TABLE public.linq_webhook_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calendar_events ADD COLUMN google_event_id text;
ALTER TABLE public.calendar_events ADD COLUMN google_calendar_id text;
ALTER TABLE public.profiles ADD COLUMN linq_verified_phone text;
COMMENT ON COLUMN public.profiles.linq_verified_phone IS 'Server-managed: verified by a signed inbound message matching an outbound chat.';
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE (availability,break_end,break_start,current_city,first_name,home_city,interests,messaging_hours,notify_appointments,notify_benefits,notify_checkins,notify_expiration,notify_sms,onboarding_complete,organization,phone,reminder_frequency,reminder_preferences,sms_consent,timezone) ON public.profiles TO authenticated;